def inspect(name, require_healthy=True):
    projection='{{json .State}}|{{json .Mounts}}|{{json .NetworkSettings.Ports}}|{{json .Config.Labels}}|{{.Image}}|{{.Config.Image}}'
    p=command([DOCKER,'inspect','--format',projection,name]).decode().strip().split('|')
    if len(p)!=6:fail('CONTAINER_PROJECTION')
    state,mounts,ports,labels=map(json.loads,p[:4])
    if (labels or {}).get('com.docker.compose.project') != PROJECT or p[4]!=IMAGE_ID or p[5]!=IMAGE:fail('CONTAINER_IDENTITY')
    if sorted((b.get('HostIp'),b.get('HostPort')) for b in (ports.get('80/tcp') or [])) != sorted(BINDINGS):fail('PORT_IDENTITY')
    if not state.get('Running') or (require_healthy and state.get('Health',{}).get('Status','healthy')!='healthy'):fail('CONTAINER_HEALTH')
    return mounts,ports

def normalization_test():
    code=b"<?php define('DOL_DOCUMENT_ROOT','/var/www/html'); ?>\n"+base64.b64decode(PAYLOAD['files']['class/PublicRequestQuotationService.class.php']['data'])+b"\n?><?php\n"+TEST_TAIL
    output=command([DOCKER,'exec','-i',CONTAINER,'php'],code).strip()
    if output!=b'PUBLIC_REQUEST_QUANTITY=PASS modern_units=3 modern_cartons=PASS legacy=PASS unknown_packing=PASS':fail('NORMALIZATION_REGRESSION_FAILED')

def staging_candidate():
    stage_state=Path('/root/chinaplanetos-web-quantity-staging/state.json')
    metadata=json.loads(read(stage_state))
    if metadata.get('status')!='DEPLOYED' or metadata.get('commit')!=PAYLOAD['commit']:fail('STAGING_ACCEPTED_COMMIT_REQUIRED')
    stage_root=Path('/var/lib/docker/volumes/erp-staging_erp-staging_custom/_data/chinaplanetoperations')
    for name,sha in STAGING_HASHES.items():
        if digest(read(stage_root/name))!=sha:fail('STAGING_CANDIDATE_DRIFT:'+name)

if __name__=='__main__':
    try: main()
    except BaseException as exc:
        # Never emit subprocess stdout/stderr or configuration contents.
        print('M085_RELEASE_FAIL='+str(exc) if isinstance(exc,RuntimeError) else 'M085_RELEASE_FAIL='+type(exc).__name__,file=sys.stderr)
        sys.exit(1)
